const defaults=()=>({version:1,zone:'village',x:0,z:13,hp:5,maxHp:5,coins:0,gears:[],collected:[],metLuna:false,bridge:false,tune:false,boss:false,bellAwake:false,power:1,defeated:[],hero:'Whisker'});
