let active=false,paused=false,scene,player,luna,camera,renderer,zoneGroup,clock=0,elapsed=0,toastTime=0,saveTimer=0,hitTimer=0,attackTimer=0,dodgeTimer=0,attackCooldown=0,locked=null,modalType='',bellNotes=[],nearest=null;
const obstacles=[],npcs=[],portals=[],collectibles=[],enemies=[],rotators=[],water=[],sparks=[],keys=new Set();let joy={x:0,y:0},yaw=0,pitch=.55,lookPointer=null,lookPrev={x:0,y:0},audioCtx=null,muted=false,velocity=new T.Vector3(),heroAngle=Math.PI,camPos=new T.Vector3(),lastFoot=0;
const V=(x,y,z)=>new T.Vector3(x,y,z),dist=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z),clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
const mats={};function mat(c){const gray=Math.round(((c>>16)&255)*.3+((c>>8)&255)*.59+(c&255)*.11);return mats[c]??=new T.MeshToonMaterial({color:(gray<<16)|(gray<<8)|gray,gradientMap:gradient})}
const gradient=new T.DataTexture(new Uint8Array([85,155,215,255]),4,1,T.RedFormat);gradient.minFilter=gradient.magFilter=T.NearestFilter;gradient.needsUpdate=true;
const outline=new T.MeshBasicMaterial({color:0x222222,side:T.BackSide});
function mesh(g,c,parent,pos=[0,0,0],scale=null,ink=true){let m=new T.Mesh(g,mat(c));m.position.set(...pos);if(scale)m.scale.set(...scale);if(ink){let o=new T.Mesh(g,outline);o.scale.setScalar(1.035);m.add(o)}parent.add(m);return m}
const sphere=new T.SphereGeometry(1,12,8),box=new T.BoxGeometry(1,1,1),cylinder=new T.CylinderGeometry(1,1,1,12),cone=new T.ConeGeometry(1,1,10);
const ball=(p,x,y,z,sx,sy,sz,c)=>mesh(sphere,c,p,[x,y,z],[sx,sy,sz]);
const cube=(p,x,y,z,sx,sy,sz,c)=>mesh(box,c,p,[x,y,z],[sx,sy,sz]);
function shadow(parent,r=1){let m=new T.Mesh(new T.CircleGeometry(r,24),new T.MeshBasicMaterial({color:0x303030,transparent:true,opacity:.16,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.y=.025;parent.add(m);return m}
function group(parent,x=0,y=0,z=0){let g=new T.Group();g.position.set(x,y,z);parent.add(g);return g}
function textSprite(text,w=3,color='#292c24',bg='#ede8d8'){let c=document.createElement('canvas');c.width=512;c.height=128;let ctx=c.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,512,128);ctx.strokeStyle=color;ctx.lineWidth=5;ctx.strokeRect(5,5,502,118);ctx.fillStyle=color;ctx.font='bold 36px Georgia';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,256,65,485);let tex=new T.CanvasTexture(c);let s=new T.Sprite(new T.SpriteMaterial({map:tex,transparent:true}));s.scale.set(w,w/4,1);return s}
function label(parent,text,x,y,z,w=3){let s=textSprite(text,w);s.position.set(x,y,z);parent.add(s);return s}
function cat(kind='Whisker',scale=1){let root=new T.Group(),body=group(root),white=kind==='Luna',fur=white?0xe9e7dc:0x989b90,dark=0x353b30,cloth=white?0x676c5e:0x3e4438;shadow(root,.65);ball(body,0,1.12,0,.36,.55,.26,cloth);ball(body,0,1.13,.245,.23,.27,.045,0xe8e5d8);ball(body,0,1.18,.295,.08,.09,.025,dark);cube(body,0,.91,0,.73,.09,.55,0xa5a99a);cube(body,0,.91,.29,.18,.14,.07,0xe8e5d8);
let head=group(body,0,1.95,0);ball(head,0,0,0,.55,.49,.42,fur);
for(let s of [-1,1]){let ear=mesh(cone,fur,head,[s*.36,.42,-.02],[.24,.42,.22]);ear.rotation.z=-s*.22;mesh(cone,0x63695c,head,[s*.36,.43,.065],[.13,.24,.12]);ball(head,s*.23,.015,.355,.235,.24,.10,dark);ball(head,s*.23,.035,.43,.125,.17,.045,0xf6f2e5);ball(head,s*.20,.02,.475,.055,.105,.025,0x23281f);ball(head,s*.13,-.24,.38,.21,.16,.16,0xe8e5d8);
for(let j=0;j<2;j++){let w=cube(head,s*.46,-.18-j*.09,.38,.3,.018,.018,dark);w.rotation.z=s*(.15-j*.3)}
if(!white){for(let j=0;j<2;j++){let stripe=cube(head,s*.43,.13+j*.13,.19,.20,.065,.10,dark);stripe.rotation.z=-s*.25}}
}ball(head,0,-.16,.535,.10,.07,.07,dark);let smile=mesh(new T.TorusGeometry(.105,.012,4,14,Math.PI),dark,head,[0,-.29,.50]);smile.rotation.z=Math.PI;ball(head,0,.36,.17,.085,.17,.08,white?fur:dark);
const legs=[],arms=[];for(let s of [-1,1]){let l=group(body,s*.20,.83,0);ball(l,0,-.27,0,.13,.34,.13,fur);ball(l,0,-.61,.12,.18,.15,.29,dark);legs.push(l);let a=group(body,s*.35,1.45,0);a.rotation.z=s*.15;ball(a,0,-.23,0,.115,.30,.12,fur);ball(a,0,-.49,.015,.16,.16,.15,0xf0ecdf);arms.push(a)}
let cape=group(body,0,1.57,-.24);let shape=new T.Shape();shape.moveTo(-.23,0);shape.lineTo(.23,0);shape.quadraticCurveTo(.5,-.55,.48,-.98);shape.quadraticCurveTo(0,-.76,-.48,-.98);shape.closePath();let capem=new T.Mesh(new T.ShapeGeometry(shape),new T.MeshToonMaterial({color:white?0x686868:0x404040,side:T.DoubleSide}));cape.add(capem);cape.rotation.x=.25;
let tail=group(body,0,.82,-.19);for(let i=0;i<6;i++)ball(tail,Math.sin(i*.38)*.38,-i*.045,-.13-i*.14,.09,.09,.14,!white&&i%2===0?dark:fur);
root.scale.setScalar(scale);root.userData={body,head,legs,arms,cape,tail};return root}
function animateCat(root,t,speed=0,attack=0,dodge=0){let a=root.userData,phase=t*10,s=Math.min(speed/3,1);a.body.position.y=Math.abs(Math.sin(phase))*s*.07;a.legs.forEach((l,i)=>l.rotation.x=Math.sin(phase+i*Math.PI)*s*.70);a.arms.forEach((l,i)=>l.rotation.x=-Math.sin(phase+i*Math.PI)*s*.55);a.head.rotation.y=Math.sin(t*.8)*.06;a.cape.rotation.x=.22+s*.45+Math.sin(t*5)*.09;a.cape.rotation.z=Math.sin(t*3)*.06;a.tail.rotation.y=Math.sin(t*3)*(.15+s*.16);if(attack>0){let p=1-attack/.42;a.arms[1].rotation.x=-Math.sin(p*Math.PI)*1.8;a.body.rotation.y=Math.sin(p*Math.PI)*.55}else a.body.rotation.y=0;a.body.rotation.x=dodge>0?-.30:0}
function tree(x,z,size=1){let g=group(zoneGroup,x,0,z);g.scale.setScalar(size);g.userData.occluder=true;mesh(new T.CylinderGeometry(.24,.37,3,7),0x686e60,g,[0,1.5,0]);let branch=cube(g,.5,2,0,1.1,.17,.18,0x686e60);branch.rotation.z=.5;ball(g,0,3.7,0,1.55,1.6,1.45,0x777f6c);ball(g,-.9,3.05,.3,.9,1,.9,0x8c9381);ball(g,.85,3.3,-.1,1,1.1,.9,0x9da48f);shadow(g,1.5);obstacles.push({x,z,r:.43*size});return g}
function house(x,z,s=1,name=''){let g=group(zoneGroup,x,0,z);g.scale.setScalar(s);cube(g,0,1.35,0,3.4,2.7,3,0xd5d5c4);let roof=mesh(new T.ConeGeometry(2.7,1.8,4),0x676e5d,g,[0,3.55,0],[1,1,.92]);roof.rotation.y=Math.PI/4;cube(g,1,3.65,-.5,.45,1.3,.5,0x838a77);cube(g,0,.90,1.52,.85,1.8,.10,0x454c3d);ball(g,.26,.85,1.6,.06,.06,.05,0xeee8d6);for(let a of [-1,1]){cube(g,a,1.6,1.53,.62,.7,.08,0x454c3d);cube(g,a,1.6,1.59,.04,.7,.04,0xc7cbb7);cube(g,a,1.6,1.59,.62,.04,.04,0xc7cbb7);cube(g,a,1.12,1.69,.82,.12,.35,0x8b937e)}if(name)label(g,name,0,2.35,1.65,2.5);shadow(g,2.3);obstacles.push({x,z,r:2*s});return g}
function gear(parent,x,y,z,size=.4,c=0xb0b5a0){let g=group(parent,x,y,z);mesh(new T.TorusGeometry(size*.7,size*.21,6,14),c,g);for(let i=0;i<8;i++){let a=i*Math.PI/4,m=cube(g,Math.sin(a)*size*.95,Math.cos(a)*size*.95,0,size*.27,size*.4,size*.3,c);m.rotation.z=-a}return g}
function pickup(id,x,z,type='coin'){if(data.collected.includes(id)||data.gears.includes(id))return;let g=group(zoneGroup,x,1,z);if(type==='gear')gear(g,0,0,0,.35,0xe9e7d6);else mesh(new T.OctahedronGeometry(.22),0xebeada,g);shadow(g,.3);collectibles.push({id,x,z,type,g});}
function circle(parent,r,color){let m=new T.Mesh(new T.RingGeometry(r*.91,r,40),new T.MeshBasicMaterial({color,side:T.DoubleSide,transparent:true,opacity:.65,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.y=.04;parent.add(m);return m}
function npc(kind,x,z,name,action){let c=cat(kind,.88);c.position.set(x,0,z);c.rotation.y=0;zoneGroup.add(c);label(zoneGroup,name,x,2.7,z,2);npcs.push({x,z,g:c,name,action});return c}
