function buildVillage(){path(0,1,4,39);path(-5,5,15,3);path(6,-6,16,3);house(-7,2,1.15,'GEAR & GRAIN');house(7,5,1,'BELLWETHER');house(-8,-9,1.2,'');house(9,-12,1.3,'');house(13,14,.9,'');for(let i=0;i<22;i++){let a=i/22*Math.PI*2;if(!(Math.cos(a)> .8 && Math.abs(Math.sin(a))<.5))tree(Math.sin(a)*20,Math.cos(a)*20,.8+(i%3)*.16)}for(let i=0;i<6;i++){ball(zoneGroup,-4+i*1.5,.15,10,.4,.2,.4,0xcdd0bc)}
let pedestal=cube(zoneGroup,0,.2,-7,3,.4,3,0x7e8870);let g=gear(zoneGroup,0,2,-7,.95,0x4f5a43);rotators.push(g);cube(zoneGroup,0,1,-7,.3,2,.3,0x5a654e);label(zoneGroup,'THE SILENT BELL',0,3.8,-7,4);
luna=npc('Luna',2.5,9,'Luna',()=>dialogue('Luna',data.bellAwake?'You did it! The first bell is awake. Beyond these woods, Baron is still stealing the rhythm of our world. We will follow the sound—together.':data.gears.length>=3?'Three winding gears! Follow the north path to the Whispering Woods. Repair the bridge, then wake the old temple bell.':"The village bell has gone silent. Baron’s clockwork beetles scattered its three winding gears! Look around the village. I’ll keep watch by the path.",()=>{data.metLuna=true;save();}));
npc('Whisker',-5.5,4.5,'Mallow · shopkeeper',showShop);
interactable(0,-18,'Whispering Woods',()=>{if(data.gears.length<3){toast('Find all 3 winding gears in the village first.');return}travel('forest',{x:0,z:22})});label(zoneGroup,'WHISPERING WOODS ↑',0,2.2,-18,4);
pickup('gear-mill',-3,-11,'gear');pickup('gear-garden',9,1,'gear');pickup('gear-well',-10,10,'gear');for(let i=0;i<14;i++)pickup('v-coin-'+i,Math.sin(i*2.4)*12,Math.cos(i*1.8)*13);
fence(-13,13,7);fence(5,-16,8);}
function buildForest(){path(0,7,3.8,40);path(7,-12,17,3);for(let i=0;i<34;i++){let x=Math.sin(i*2.399)* (8+(i%6)*3),z=Math.cos(i*2.399)*(10+(i%5)*3);if(Math.abs(x)<4)x+=Math.sign(x||1)*5;tree(x,z,.8+(i%4)*.13)}
let river=cube(zoneGroup,0,-.03,-8,55,.07,4,0x64735c);water.push(river);for(let i=0;i<11;i++)cube(zoneGroup,(i-5)*4,.01,-8+Math.sin(i)*.5,1.3,.025,.05,0xc6d1bb);
for(let i=0;i<7;i++)cube(zoneGroup,0,.12,-10+i*.65,3.3,.20,.55,0x7c866a);fence(-1.65,-10,5,'z');fence(1.65,-10,5,'z');
gate=group(zoneGroup,0,0,-5.8);cube(gate,0,.8,0,4,1.6,.25,0x5c684e);gear(gate,0,1,0,.50,0xd0d4bc);gate.visible=!data.bridge;if(!data.bridge)obstacles.push({x:0,z:-5.8,r:2.2,gate:true});
let lever=group(zoneGroup,3.3,0,-3.7);cube(lever,0,.35,0,1,.7,1,0x6e795f);let handle=cube(lever,0,1,0,.12,1,.12,0xdde0cc);handle.rotation.z=-.5;gear(lever,.4,1.5,0,.22,0xdde0cc);interactable(3.3,-3.7,'Repair bridge mechanism',()=>{if(!data.bridge){data.bridge=true;gate.visible=false;toast('Bridge repaired. The clockwork temple awaits.');tone(392);save();updateHud()}else toast('The bridge is working. Cross north toward the temple.')});label(zoneGroup,'BRIDGE WINDING POST',3.5,2.6,-3.8,3.5);
beetle(-1,11,'beetle-a');beetle(2,2,'beetle-b');beetle(-2,-16,'beetle-c');for(let i=0;i<12;i++)pickup('f-coin-'+i,Math.sin(i*2)*4,(i-6)*3.5);
let portal=group(zoneGroup,0,0,-24);cube(portal,-2.1,2,0,.7,4,.8,0xc0c8ad);cube(portal,2.1,2,0,.7,4,.8,0xc0c8ad);cube(portal,0,4.1,0,5,.7,1,0xc0c8ad);gear(portal,0,4.5,.6,.6,0x414d36);label(zoneGroup,'CLOCKWORK TEMPLE',0,5.2,-24,4.5);interactable(0,-23,'Enter Clockwork Temple',()=>{if(!data.bridge){toast('Repair the bridge mechanism first.');return}travel('temple',{x:0,z:17})});interactable(0,24,'Return to Bellwether Village',()=>travel('village',{x:0,z:-15}));label(zoneGroup,'VILLAGE ↓',0,2,24,3);}
function buildTemple(){// A deliberately original bell courtyard and guardian chamber.
path(0,0,8,42);path(0,6,31,4);for(let side of [-1,1]){for(let i=0;i<7;i++){cube(zoneGroup,side*18,2,i*6-18,1.2,4,5.8,0x6e7a5f);cube(zoneGroup,side*17.3,3.9,i*6-18,1.4,.3,1.2,0xb7c1a4)}for(let i=0;i<4;i++){let z=i*10-14;mesh(cylinder,0xaab699,zoneGroup,[side*7,1.8,z],[.65,3.6,.65]);mesh(cylinder,0x535f45,zoneGroup,[side*7,3.8,z],[.9,.4,.9]);obstacles.push({x:side*7,z,r:.85})}}
for(let i=0;i<15;i++){cube(zoneGroup,Math.sin(i*5)*15,.03,Math.cos(i*4)*19,1.4,.08,1.4,0xc2cbb0)}
let locs=[[-11,7],[11,7],[0,-2]];locs.forEach(([x,z],i)=>{let g=group(zoneGroup,x,0,z);cube(g,0,.25,0,2,.5,2,0x657254);mesh(new T.CylinderGeometry(.3,.8,1.1,16),0xb9c3a4,g,[0,1.8,0]);ball(g,0,1.25,0,.13,.18,.13,0x333f27);cube(g,-1.1,1.6,0,.15,3.2,.15,0x3a482d);cube(g,1.1,1.6,0,.15,3.2,.15,0x3a482d);cube(g,0,3.2,0,2.4,.18,.18,0x3a482d);label(g,['I · LOW','II · MIDDLE','III · HIGH'][i],0,.7,.8,2.2);interactable(x,z,'Ring bell '+(i+1),()=>ringBell(i));});
label(zoneGroup,'A SONG OPENS THE WAY',0,3.7,12,4);interactable(0,12,'Read the inscription',()=>dialogue('The bellkeeper’s inscription','“First the middle voice calls, then the low voice answers, then the high voice welcomes the dawn.” Ring the three bells in that order. A wrong note starts the melody over.'));cube(zoneGroup,0,.6,12,1.5,1.2,.6,0x758364);
gate=group(zoneGroup,0,0,-7);for(let i=-3;i<=3;i++)cube(gate,i,2,0,.12,4,.18,0x37472a);cube(gate,0,4,0,7,.3,.3,0x37472a);gate.visible=!data.tune;if(!data.tune)obstacles.push({x:0,z:-7,r:3.4,gate:true});
let warden=beetle(0,-15,'warden',true);if(warden)warden.g.rotation.y=0;
let bell=group(zoneGroup,0,0,-21);cube(bell,0,.25,0,4,.5,3,0x626f50);for(let s of [-1,1])cube(bell,s*1.7,2.2,0,.35,4.4,.4,0x4b5a39);cube(bell,0,4.5,0,4,.4,.5,0x4b5a39);mesh(new T.CylinderGeometry(.55,1.2,1.8,18),0xcbd1b8,bell,[0,3.15,0]);ball(bell,0,2.2,0,.2,.3,.2,0x354426);interactable(0,-21,'Wake the village bell',()=>{if(!data.boss){toast('Defeat the Clockwork Warden first.');return}chapterComplete()});interactable(0,20,'Return to Whispering Woods',()=>travel('forest',{x:0,z:-20}));label(zoneGroup,'WOODS ↓',0,2.2,20,3);for(let i=0;i<8;i++)pickup('t-coin-'+i,(i%2?1:-1)*12,(i-4)*4);}
function ringBell(i){if(data.tune){toast('The melody is complete. The gate is open.');return}tone([261.63,329.63,392][i],.4);bellNotes.push(i);const seq=[1,0,2];if(bellNotes.some((n,k)=>n!==seq[k])){bellNotes=[];toast('The melody slips away. Try middle, low, high.');return}toast(['A clear note…','The bells begin to resonate…','The guardian gate opens!'][bellNotes.length-1]);if(bellNotes.length===3){data.tune=true;gate.visible=false;save();updateHud()}}
function showShop(){modalType='shop';showModal(`<div class="label">GEAR & GRAIN · CAT-OWNED VILLAGE SHOP</div><h2>Mallow’s provisions</h2><p>“A little preparation goes a long way, hero.”</p><p>You have <b>${data.coins} clockwork coins</b>.</p><button class="choice" id="buyHeal">Warm milk · restore all hearts <b>— 6 coins</b></button><button class="choice" id="buyPower">Reinforced gloves · +1 attack power <b>— ${data.power>=2?'OWNED':'12 coins'}</b></button><p class="muted">All currency is earned in-game. No purchases or payments.</p>`);$('buyHeal').onclick=()=>{if(data.hp===data.maxHp){toast('Your hearts are already full.');return}if(data.coins<6){toast('You need 6 coins.');return}data.coins-=6;data.hp=data.maxHp;save();updateHud();showShop();tone(523)};$('buyPower').onclick=()=>{if(data.power>=2){toast('You already own reinforced gloves.');return}if(data.coins<12){toast('You need 12 coins.');return}data.coins-=12;data.power=2;save();showShop();updateHud();tone(523)}}
function dialogue(who,text,done){showModal(`<div class="label">BELLWETHER CHRONICLES</div><h2>${who}</h2><p>${text}</p><button class="choice" id="dialogDone">Onward →</button>`);$('dialogDone').onclick=()=>{closeModal();done?.();updateHud()}}
function chapterComplete(){data.boss=true;data.bellAwake=true;save();tone(523,.8);showModal(`<div class="label">CHAPTER 01 COMPLETE</div><h2>The bell rings again.</h2><p>Its first note drifts over the bridge and through Bellwether’s quiet streets. Whisker and Luna have brought the village its rhythm back.</p><p>Far beyond the woods, Baron’s machines are still turning. This is the beginning of their adventure.</p><p class="muted">You have reached the end of this early playable chapter. Additional regions, final character art, and Baron’s final encounter are still to be built. Your progress is saved on this device.</p><button class="choice" id="backVillage">Return to the village →</button>`);$('backVillage').onclick=()=>{closeModal();travel('village',{x:0,z:12})}}
function showModal(html){paused=true;joy={x:0,y:0};keys.clear();$('knob').style.transform='';$('modalContent').innerHTML=html;$('modal').classList.remove('hidden')}
function closeModal(){$('modal').classList.add('hidden');paused=false;modalType=''}$('closeModal').onclick=closeModal;
function pauseMenu(){save();showModal(`<div class="label">TAKE A BREATHER</div><h2>Your journey, saved.</h2><p>${data.gears.length}/3 winding gears · ${data.coins} coins · ${data.power===2?'Reinforced':'Standard'} gloves</p><div class="row"><button id="continuePlay">Resume</button><button id="soundToggle">Sound: ${muted?'off':'on'}</button><button id="full">Fullscreen</button></div><h3>Keep your progress</h3><p class="muted">Autosaves on this browser. Export a backup to keep your progress if browser data is cleared or to move devices. Development source is saved separately.</p><div class="row"><button id="export">Export save</button><button id="import">Import save</button><button id="restart" class="danger">New journey</button></div><p class="muted">WASD / arrows: move • drag right side: camera • Space: attack • Shift: dodge • E: interact • Q: target lock. On touchscreens, use the joystick and action buttons. Rotate your phone to landscape for more room.</p>`);$('continuePlay').onclick=closeModal;$('soundToggle').onclick=()=>{muted=!muted;pauseMenu()};$('full').onclick=()=>document.documentElement.requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this browser.'));$('export').onclick=()=>{let blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='super-paw-clockwork-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import').onclick=()=>$('importFile').click();$('restart').onclick=()=>{showModal('<div class="label">START AGAIN?</div><h2>A fresh journey</h2><p>This replaces your progress on this device. Export a save first if you want to keep it.</p><div class="row"><button id="yesReset">Start new journey</button><button id="noReset">Keep my journey</button></div>');$('yesReset').onclick=()=>{data=defaults();closeModal();buildZone('village');save()};$('noReset').onclick=pauseMenu}}
$('importFile').onchange=async e=>{let file=e.target.files[0];if(!file)return;try{let d=JSON.parse(await file.text());if(!validSave(d))throw Error('Invalid');data={...defaults(),...d};closeModal();buildZone(data.zone,{x:data.x,z:data.z});save();toast('Backup restored.')}catch{toast('That file is not a valid Clockwork Adventure save.')}e.target.value=''};
function validSave(d){return d&&d.version===1&&['village','forest','temple'].includes(d.zone)&&['x','z','hp','maxHp','coins','power'].every(k=>typeof d[k]==='number'&&Number.isFinite(d[k]))&&Math.abs(d.x)<=28&&Math.abs(d.z)<=28&&d.hp>0&&d.hp<=5&&d.maxHp===5&&d.coins>=0&&d.coins<=100000&&(d.power===1||d.power===2)&&['gears','collected','defeated'].every(k=>Array.isArray(d[k])&&d[k].length<1000&&d[k].every(x=>typeof x==='string'))&&d.gears.length<=3&&['metLuna','bridge','tune','boss'].every(k=>typeof d[k]==='boolean')}
function showMap(){let z=data.zone;showModal(`<div class="label">YOUR FIELD GUIDE</div><h2>The Bellwether valley</h2><p class="muted">Walk to a marked exit and use the interact button to travel. New regions will be added as the adventure grows.</p>${[['village','⌂','Bellwether Village','Luna · provisions · 3 gears'],['forest','♧','Whispering Woods','Clockwork beetles · bridge'],['temple','♜','Clockwork Temple','Three bells · guardian']].map(([id,icon,name,desc])=>`<div class="mapline ${z===id?'current':''}"><em>${icon}</em><b>${name}<br><span>${desc}</span></b><span>${z===id?'YOU ARE HERE':''}</span></div>`).join('')}<p>${objective()}</p>`)}
function objective(){if(data.bellAwake)return 'The first bell is awake. Return to Luna in the village.';if(data.zone==='temple')return data.boss?'Wake the great bell at the back of the chamber.':data.tune?'Defeat the Warden, then wake the great bell.':'Read the inscription. Play the three bells in order.';if(data.zone==='forest')return data.bridge?'Cross the bridge and enter the Clockwork Temple.':'Find the winding post and repair the woodland bridge.';return data.gears.length<3?`Find the village’s winding gears (${data.gears.length}/3). Talk to Luna beside the path.`:'Follow the north path into Whispering Woods.'}
function updateHud(){$('hearts').textContent='♥ '.repeat(Math.max(0,data.hp))+'♡ '.repeat(Math.max(0,data.maxHp-data.hp));$('coins').textContent=`◈ ${data.coins}   ⚙ ${data.gears.length}/3`;$('place').textContent={village:'Bellwether Village',forest:'Whispering Woods',temple:'Clockwork Temple'}[data.zone];$('region').textContent=data.zone==='temple'?'THE FIRST DUNGEON':'PAWTOPIA · BELLWETHER VALLEY';$('objective').textContent=objective();}
function save(){if(!active)return;data.x=player.position.x;data.z=player.position.z;try{localStorage.setItem(KEY,JSON.stringify(data));$('saveState').textContent='SAVED LOCALLY'}catch{$('saveState').textContent='SAVE UNAVAILABLE · EXPORT A BACKUP'}}
function travel(zone,spawn){save();buildZone(zone,spawn);hitTimer=1;save();toast($('place').textContent)}
function toast(text){$('toast').textContent=text;$('toast').style.opacity='1';toastTime=3.5}
function tone(freq=440,dur=.12){if(muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.045,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch{}}
function burst(pos,count=8){for(let i=0;i<count;i++){let m=mesh(new T.OctahedronGeometry(.06),0xf4f0db,scene,[pos.x,pos.y+1,pos.z],null,false);sparks.push({g:m,v:V((Math.random()-.5)*5,Math.random()*4,(Math.random()-.5)*5),life:.6})}}
function attack(){if(!active||paused||attackCooldown>0||dodgeTimer>0)return;attackTimer=.42;attackCooldown=.48;tone(180,.07);let hit=false;for(let e of enemies){if(e.hp<=0||(e.boss&&!data.tune))continue;let d=dist(player.position,e);if(d<(e.boss?3.0:2.0)){let angle=Math.atan2(e.x-player.position.x,e.z-player.position.z),diff=Math.atan2(Math.sin(angle-heroAngle),Math.cos(angle-heroAngle));if(Math.abs(diff)<1.65){e.hp-=data.power;e.hurt=.2;burst(e.g.position);hit=true;if(e.hp<=0){data.coins+=e.boss?15:3;data.defeated.push(e.id);e.g.visible=false;if(e.boss){data.boss=true;toast('Warden defeated! Wake the great bell at the back of the chamber.');$('bossHud').classList.add('hidden')}else toast('+3 clockwork coins');locked=null;save();updateHud()}}}}if(hit)tone(110,.12)}
function dodge(){if(!active||paused||dodgeTimer>0)return;dodgeTimer=.36;hitTimer=Math.max(hitTimer,.42);if(velocity.length()<.1)velocity.set(Math.sin(heroAngle)*5,0,Math.cos(heroAngle)*5);tone(220,.05)}
function lockTarget(){if(locked){locked=null;toast('Target released');return}locked=enemies.filter(e=>e.hp>0&&dist(player.position,e)<14).sort((a,b)=>dist(player.position,a)-dist(player.position,b))[0]||null;toast(locked?'Target locked':'No enemy nearby')}
function use(){if(!active||paused)return;if(nearest){nearest.action();tone(440,.05)}else toast('Move closer to a person, sign, bell, or exit.')}
function hurt(){if(hitTimer>0)return;data.hp--;hitTimer=1.3;burst(player.position,6);tone(95,.25);if(data.hp<=0){data.hp=data.maxHp;data.coins=Math.max(0,data.coins-2);buildZone(data.zone,{x:0,z:data.zone==='forest'?22:data.zone==='temple'?17:13});toast('Take a breath. You returned safely; 2 coins were lost.')}updateHud();save()}
function canMove(x,z){if(Math.abs(x)>bounds||Math.abs(z)>bounds)return false;if(data.zone==='forest'&&z<-5.5&&z>-10.7&&Math.abs(x)>1.35)return false;for(let o of obstacles){if(o.gate&&((data.zone==='forest'&&data.bridge)||(data.zone==='temple'&&data.tune)))continue;if(Math.hypot(x-o.x,z-o.z)<o.r+.32)return false}if(data.zone==='temple'&&!data.tune&&z<-6)return false;return true}
function init(){try{try{renderer=new T.WebGLRenderer({canvas:$('game'),antialias:true,powerPreference:'high-performance'})}catch{renderer=new SoftwareRenderer({canvas:$('game')});$('keyboardHint').textContent='Compatibility graphics · WASD move · Drag to look · E interact · Space attack'};renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setSize(innerWidth,innerHeight);renderer.setClearColor(0xd8d8d4);renderer.outputColorSpace=T.SRGBColorSpace;try{pathTexture=new T.TextureLoader().load('./assets/ink-cobblestone.png');pathTexture.wrapS=pathTexture.wrapT=T.RepeatWrapping;pathTexture.colorSpace=T.SRGBColorSpace}catch{}scene=new T.Scene();scene.fog=new T.Fog(0xd8d8d4,25,65);scene.add(new T.HemisphereLight(0xffffff,0x707070,2.0));let sun=new T.DirectionalLight(0xffffff,2.0);sun.position.set(-12,20,8);scene.add(sun);camera=new T.PerspectiveCamera(53,innerWidth/innerHeight,.1,120);player=cat();scene.add(player);return true}catch(err){showModal('<h2>3D graphics unavailable</h2><p>This browser could not start WebGL. Try opening the game in Chrome on your phone.</p>');return false}}
function start(resume=false){if(!renderer&&!init())return;data=resume&&validSave(saved)?{...defaults(),...saved}:defaults();active=true;paused=false;$('title').classList.add('hidden');$('hud').classList.remove('hidden');buildZone(data.zone,{x:data.x,z:data.z});save();tone(392,.3);if(!resume)dialogue('Welcome to Bellwether','The morning bell has stopped. Whisker and Luna set out to discover why. Move with the joystick, drag the open right side of the screen to look around, and use ✦ to talk to Luna.');}
$('begin').onclick=()=>{if(saved&&validSave(saved)){showModal('<h2>Begin a new journey?</h2><p>A saved journey already exists. Starting again will replace it on this browser.</p><div class="row"><button id="startFresh">Start new</button><button id="keepSave">Continue saved</button></div>');$('startFresh').onclick=()=>{closeModal();start(false)};$('keepSave').onclick=()=>{closeModal();start(true)}}else start(false)};$('resume').onclick=()=>start(true);$('pauseButton').onclick=pauseMenu;$('mapButton').onclick=showMap;$('attack').onpointerdown=e=>{e.preventDefault();attack()};$('dodge').onpointerdown=e=>{e.preventDefault();dodge()};$('interact').onclick=use;$('lock').onclick=lockTarget;
let stickId=null;function stickMove(e){let r=$('stick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,max=r.width*.32,len=Math.hypot(dx,dy);if(len>max){dx*=max/len;dy*=max/len}joy={x:dx/max,y:dy/max};$('knob').style.transform=`translate(${dx}px,${dy}px)`}
$('stick').onpointerdown=e=>{e.preventDefault();stickId=e.pointerId;$('stick').setPointerCapture(e.pointerId);stickMove(e)};$('stick').onpointermove=e=>{if(e.pointerId===stickId)stickMove(e)};function resetStick(){stickId=null;joy={x:0,y:0};$('knob').style.transform=''}$('stick').onpointerup=$('stick').onpointercancel=resetStick;
$('game').onpointerdown=e=>{if(!active||paused)return;lookPointer=e.pointerId;lookPrev={x:e.clientX,y:e.clientY};$('game').setPointerCapture(e.pointerId)};$('game').onpointermove=e=>{if(e.pointerId!==lookPointer)return;yaw-=(e.clientX-lookPrev.x)*.006;pitch=clamp(pitch+(e.clientY-lookPrev.y)*.003,.25,.95);lookPrev={x:e.clientX,y:e.clientY}};$('game').onpointerup=$('game').onpointercancel=()=>lookPointer=null;
window.onkeydown=e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;keys.add(e.code);if(e.code==='Escape'&&active){if(paused)closeModal();else pauseMenu()}if(e.code==='KeyE')use();if(e.code==='Space')attack();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dodge();if(e.code==='KeyQ')lockTarget()};window.onkeyup=e=>keys.delete(e.code);window.addEventListener('blur',()=>{keys.clear();resetStick();if(active&&!paused)pauseMenu()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active){save();keys.clear();resetStick();if(!paused)pauseMenu()}});window.onresize=()=>{if(!renderer)return;renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()};window.addEventListener('pagehide',save);
function frame(time){requestAnimationFrame(frame);let dt=Math.min((time-elapsed)/1000||.016,.04);elapsed=time;if(!active||!renderer)return;if(!paused){clock+=dt;hitTimer=Math.max(0,hitTimer-dt);attackTimer=Math.max(0,attackTimer-dt);attackCooldown=Math.max(0,attackCooldown-dt);dodgeTimer=Math.max(0,dodgeTimer-dt);toastTime-=dt;if(toastTime<=0)$('toast').style.opacity=0;
let mx=joy.x+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),my=joy.y+(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0),l=Math.hypot(mx,my);if(l>1){mx/=l;my/=l}let speed=attackTimer>0?1.3:4.6;if(dodgeTimer<=0){let target=V((mx*Math.cos(yaw)+my*Math.sin(yaw))*speed,0,(-mx*Math.sin(yaw)+my*Math.cos(yaw))*speed);velocity.lerp(target,1-Math.exp(-dt*13))}let mult=dodgeTimer>0?2.1:1,nx=player.position.x+velocity.x*dt*mult,nz=player.position.z+velocity.z*dt*mult;if(canMove(nx,player.position.z))player.position.x=nx;if(canMove(player.position.x,nz))player.position.z=nz;
if(locked&&locked.hp>0){heroAngle=Math.atan2(locked.x-player.position.x,locked.z-player.position.z)}else if(velocity.length()>.15)heroAngle=Math.atan2(velocity.x,velocity.z);let dif=Math.atan2(Math.sin(heroAngle-player.rotation.y),Math.cos(heroAngle-player.rotation.y));player.rotation.y+=dif*(1-Math.exp(-dt*15));animateCat(player,clock,velocity.length(),attackTimer,dodgeTimer);player.visible=hitTimer<=0||Math.sin(clock*35)>-.5;
for(let n of npcs){animateCat(n.g,clock+.3,0);let d=dist(player.position,n);if(d<5){let a=Math.atan2(player.position.x-n.x,player.position.z-n.z);n.g.rotation.y+=Math.atan2(Math.sin(a-n.g.rotation.y),Math.cos(a-n.g.rotation.y))*.04}}
for(let i=collectibles.length-1;i>=0;i--){let c=collectibles[i];c.g.rotation.y+=dt*1.7;c.g.position.y=1+Math.sin(clock*2+i)*.12;if(dist(player.position,c)<.9){if(c.type==='gear'){data.gears.push(c.id);toast(`Winding gear found · ${data.gears.length}/3`);tone(659,.3)}else{data.coins++;data.collected.push(c.id);tone(880,.06)}zoneGroup.remove(c.g);collectibles.splice(i,1);save();updateHud()}}
for(let r of rotators)r.rotation.z+=dt*.35;for(let i=0;i<water.length;i++)water[i].position.y=-.04+Math.sin(clock*1.5)*.008;
let bossNear=false;for(let e of enemies){if(e.hp<=0)continue;if(e.boss&&!data.tune)continue;let d=dist(player.position,e);e.cool-=dt;e.hurt=Math.max(0,e.hurt-dt);e.g.visible=e.hurt<=0||Math.sin(clock*50)>-.5;e.g.position.y=Math.sin(clock*10)*.04;if(e.boss&&d<17){bossNear=true;$('bossHealth').style.width=(e.hp/e.max*100)+'%'}
if(e.mode==='windup'){e.timer-=dt;e.ring.visible=true;e.g.scale.setScalar((e.boss?2:1)*(1+Math.sin(clock*30)*.035));if(e.timer<=0){e.mode='recover';e.timer=e.boss?1.1:.8;e.ring.visible=false;if(d<(e.boss?3.3:1.65))hurt();burst(e.g.position,e.boss?16:5)}}else if(e.mode==='recover'){e.timer-=dt;if(e.timer<=0){e.mode='idle';e.cool=.8;e.g.scale.setScalar(e.boss?2:1)}}else if(d<12){e.g.rotation.y=Math.atan2(player.position.x-e.x,player.position.z-e.z);let reach=e.boss?2.5:1.2;if(d>reach){let sp=e.boss?1.25:1.7,dx=(player.position.x-e.x)/d*dt*sp,dz=(player.position.z-e.z)/d*dt*sp;if(canMove(e.x+dx,e.z+dz)){e.x+=dx;e.z+=dz;e.g.position.x=e.x;e.g.position.z=e.z}}else if(e.cool<=0){e.mode='windup';e.timer=e.boss?.9:.65}}e.ring.material.opacity=.35+Math.sin(clock*12)*.25;}
$('bossHud').classList.toggle('hidden',!bossNear);for(let i=sparks.length-1;i>=0;i--){let s=sparks[i];s.life-=dt;s.v.y-=dt*8;s.g.position.addScaledVector(s.v,dt);if(s.life<=0){scene.remove(s.g);s.g.geometry.dispose();sparks.splice(i,1)}}
nearest=null;let best=Infinity;for(let n of [...npcs,...portals]){let d=dist(player.position,n);if(d<(n.r||2.5)&&d<best){best=d;nearest=n}}$('prompt').textContent=nearest?`✦ ${nearest.name}`:'';$('lock').style.background=locked?'#777e69':'#22271dcc';
let targetCam=player.position.clone().add(V(Math.sin(yaw)*10,3.5+pitch*5,Math.cos(yaw)*10));camPos.lerp(targetCam,1-Math.exp(-dt*6));camera.position.copy(camPos);camera.lookAt(player.position.clone().add(V(0,1.2,0)));for(let g of zoneGroup.children){if(g.userData.occluder)g.visible=dist(camPos,g.position)>5;}saveTimer+=dt;if(saveTimer>5){saveTimer=0;save()}}
renderer.render(scene,camera)}requestAnimationFrame(frame);
